import {
  Mesh,
  Group,
  PlaneGeometry,
  Vector2,
  Vector3,
  Color,
  DoubleSide,
  Object3D,
} from 'three/webgpu';
import {
  mix,
  float,
  vec2,
  vec3,
  texture,
  positionLocal,
  uv,
  add,
  sub,
  mul,
  divide,
  lessThan,
  step,
  noiseSimplex,
  transformDirection,
  normalWorld,
  reflect,
  dot,
  max,
  saturate,
  pow,
  sin,
  abs,
  normalize,
  length,
  pow2,
  pow3,
} from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const root = new Group();
  // apply placement
  if (config.position) root.position.set(...config.position);
  if (config.rotation) root.rotation.set(...config.rotation);
  if (config.scale) root.scale.set(...config.scale);

  // ---------- Background plane ----------
  const bgWidth = 7;
  const bgHeight = 5.5;
  const bgGeom = new PlaneGeometry(bgWidth, bgHeight);
  const bgMat = new Mesh.BasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
    color: mix(
      new Color('#0b0b10'),
      new Color('#14141a'),
      // vertical gradient based on local Y position normalized to [0,1]
      (add(positionLocal.y, bgHeight / 2).div(bgHeight))
    ),
  });

  // add subtle grain (1.5% monochrome)
  const grainNode = mul(
    noiseSimplex(uv.mul(200)).abs(),
    0.015
  );
  bgMat.color = add(bgMat.color, grainNode);

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -0.01);
  root.add(bgMesh);

  // ---------- Text specifications ----------
  const leftX = -3.1;
  const baseline = 0.25; // grid unit
  const lines = [
    {
      type: 'kicker',
      text: 'NOVA ATELIER / JOURNAL',
      style: {
        family: 'JetBrains Mono',
        fontSize: 18,
        fontWeight: 700,
        letterSpacing: 0.12,
        lineHeight: 1.4,
        color: '#16161d',
        uppercase: true,
      },
      y: 1.7,
    },
    {
      type: 'hero',
      text: 'PRECISION IS',
      style: {
        family: 'Lora',
        fontSize: 124,
        fontWeight: 600,
        letterSpacing: -0.015,
        lineHeight: 0.98,
        color: '#16161d',
      },
      y: 0.9,
    },
    {
      type: 'hero',
      text: 'A HABIT.',
      style: {
        family: 'Lora',
        fontSize: 124,
        fontWeight: 600,
        letterSpacing: -0.015,
        lineHeight: 0.98,
        color: '#16161d',
      },
      y: 0.25,
    },
    {
      type: 'body',
      text: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
      style: {
        family: 'JetBrains Mono',
        fontSize: 26,
        fontWeight: 400,
        letterSpacing: 0,
        lineHeight: 1.55,
        color: '#16161d',
        maxWidth: 4.5,
      },
      y: -0.8,
    },
    {
      type: 'caption',
      text: 'ISSUE 12 / JULY 2026',
      style: {
        family: 'JetBrains Mono',
        fontSize: 18,
        fontWeight: 400,
        letterSpacing: 0.08,
        lineHeight: 1.4,
        color: '#16161d',
      },
      y: -1.9,
    },
  ];

  const textMeshes = [];

  lines.forEach((ln) => {
    const txt = ln.text;
    const style = ln.style;
    const mesh = createTextMesh(txt, {
      atlas: ctx.fontAtlas,
      fontFamily: style.family,
      fontSize: style.fontSize,
      fontWeight: style.fontWeight,
      letterSpacing: style.letterSpacing,
      lineHeight: style.lineHeight,
      color: style.color,
      maxWidth: style.maxWidth,
      uppercase: style.uppercase,
      anchor: 'left-top',
    });
    mesh.position.set(leftX, ln.y, 0);
    root.add(mesh);
    textMeshes.push({ mesh, type: ln.type });
  });

  // ---------- Hero shadow duplicate ----------
  const heroLines = lines.filter((ln) => ln.type === 'hero');
  const shadowMeshes = [];

  heroLines.forEach((ln) => {
    const shadow = createTextMesh(ln.text, {
      atlas: ctx.fontAtlas,
      fontFamily: ln.style.family,
      fontSize: ln.style.fontSize,
      fontWeight: ln.style.fontWeight,
      letterSpacing: ln.style.letterSpacing,
      lineHeight: ln.style.lineHeight,
      color: '#16161d',
      anchor: 'left-top',
    });
    shadow.position.set(leftX - 0.02, ln.y - 0.02, -0.02);
    root.add(shadow);
    shadowMeshes.push(shadow);
  });

  // ---------- Underline rule ----------
  const ruleWidth = 2.2;
  const ruleHeight = 0.05;
  const ruleGeom = new PlaneGeometry(ruleWidth, ruleHeight);
  const ruleMat = new Mesh.BasicNodeMaterial({
    side: DoubleSide,
    color: new Color('#ff2a38'),
    emissive: new Color('#ff2a38').multiplyScalar(1.2),
    transparent: true,
  });
  const ruleMesh = new Mesh(ruleGeom, ruleMat);
  ruleMesh.position.set(leftX + ruleWidth / 2, -0.15, 0);
  ruleMesh.scale.set(0, 1, 1); // start collapsed
  root.add(ruleMesh);

  // ---------- GSAP animations ----------
  const timeline = gsap.timeline({ defaults: { ease: 'power3.out' } });

  // rise-in per block top-to-bottom with stagger 0.08s
  const riseBlocks = [...textMeshes.map(t => t.mesh), ...shadowMeshes];
  riseBlocks.forEach((m, i) => {
    m.position.y += 0.4;
    m.visible = true;
    timeline.fromTo(
      m.position,
      { y: m.position.y },
      { y: m.position.y - 0.4, opacity: 1, duration: 0.7 },
      i * 0.08
    );
  });

  // after hero lands (last hero block), animate rule scaleX
  const heroLastIdx = textMeshes.findIndex(t => t.type === 'hero' && t.mesh.position.y === heroLines[heroLines.length - 1].y);
  const heroLandTime = (heroLastIdx + 1) * 0.08 + 0.7;
  timeline.to(
    ruleMesh.scale,
    { x: 1, duration: 0.5, ease: 'power2.out' },
    heroLandTime
  );

  // store timeline for cleanup
  root.userData.timeline = timeline;

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    timeline.kill();
    bgGeom.dispose();
    bgMat.dispose();
    ruleGeom.dispose();
    ruleMat.dispose();
    textMeshes.forEach(t => {
      if (t.mesh.geometry) t.mesh.geometry.dispose();
      if (t.mesh.material) t.mesh.material.dispose();
    });
    shadowMeshes.forEach(m => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) m.material.dispose();
    });
  };

  // ---------- Handlers placeholder ----------
  root.userData.handlers = {};

  // apply any cinematic primitives (none in this spec)
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives && typeof ctx.primitives[primitive.name] === 'function') {
        ctx.primitives[primitive.name](root, primitive.params);
      }
    });
  }

  return root;
}
